1	package txsaga
2	
3	import (
4		"context"
5		"strings"
6		"sync"
7		"time"
8	)
9	
10	// ValidateDefinition 校验 Saga 定义，非法时返回 ErrInvalidDefinition（可 errors.Is）。
11	// 规则：名称非空、至少一个步骤、每个步骤名非空且不重复、每个步骤都提供正向
12	// 动作；任一动作/补偿的重试最大总调用次数为负、失败等待时长为负同样非法。
13	// 未配置的重试预算按最大 1 次、等待 0 处理。
14	// 步骤声明的前置（DependsOn）必须指向定义内已存在的其它步骤：前置名称未知、
15	// 自依赖、同一前置重复声明或前置关系成环均属非法定义。
16	func ValidateDefinition(d Definition) error {
17		if strings.TrimSpace(d.Name) == "" {
18			return ErrInvalidDefinition
19		}
20		if len(d.Steps) == 0 {
21			return ErrInvalidDefinition
22		}
23		seen := make(map[string]struct{}, len(d.Steps))
24		for _, st := range d.Steps {
25			if strings.TrimSpace(st.Name) == "" || st.Action == nil {
26				return ErrInvalidDefinition
27			}
28			if _, dup := seen[st.Name]; dup {
29				return ErrInvalidDefinition
30			}
31			if st.ActionRetry.MaxAttempts < 0 || st.ActionRetry.RetryWait < 0 ||
32				st.CompensateRetry.MaxAttempts < 0 || st.CompensateRetry.RetryWait < 0 {
33				return ErrInvalidDefinition
34			}
35			seen[st.Name] = struct{}{}
36		}
37		return validateDeps(d.Steps)
38	}
39	
40	// validateDeps 校验各步骤声明的前置关系：前置必须存在、不得自依赖、不得重复，
41	// 且前置关系不得成环。
42	func validateDeps(steps []Step) error {
43		index := make(map[string]int, len(steps))
44		for i, st := range steps {
45			index[st.Name] = i
46		}
47		deps := make([][]int, len(steps))
48		for i, st := range steps {
49			dup := make(map[string]struct{}, len(st.DependsOn))
50			for _, dep := range st.DependsOn {
51				if dep == st.Name {
52					return ErrInvalidDefinition // 自依赖
53				}
54				j, ok := index[dep]
55				if !ok {
56					return ErrInvalidDefinition // 前置未知
57				}
58				if _, exists := dup[dep]; exists {
59					return ErrInvalidDefinition // 重复前置
60				}
61				dup[dep] = struct{}{}
62				deps[i] = append(deps[i], j)
63			}
64		}
65		// 三色 DFS 检测环：灰色表示当前递归栈上，再次遇到即成环。
66		const (
67			white = iota // 未访问
68			gray         // 递归栈上
69			black        // 已完成
70		)
71		color := make([]int, len(steps))
72		var cyclic func(i int) bool
73		cyclic = func(i int) bool {
74			color[i] = gray
75			for _, j := range deps[i] {
76				if color[j] == gray || (color[j] == white && cyclic(j)) {
77					return true
78				}
79			}
80			color[i] = black
81			return false
82		}
83		for i := range steps {
84			if color[i] == white && cyclic(i) {
85				return ErrInvalidDefinition
86			}
87		}
88		return nil
89	}
90	
91	// Engine 在给定 Store 上执行 Saga。零值不可用，请用 NewEngine 创建。
92	type Engine struct {
93		store Store
94	
95		// 同执行身份的进程内串行化，避免并发调用重复进入同一未确认动作。
96		locksMu sync.Mutex
97		locks   map[string]*sync.Mutex
98	
99		// now 为可注入时钟；生产使用 time.Now。
100		now func() time.Time
101	}
102	
103	// NewEngine 创建基于 store 的编排引擎。
104	func NewEngine(store Store) *Engine {
105		return &Engine{store: store, locks: make(map[string]*sync.Mutex), now: time.Now}
106	}
107	
108	func (e *Engine) identityLock(businessKey, idempotencyKey string) *sync.Mutex {
109		key := businessKey + "\x00" + idempotencyKey
110		e.locksMu.Lock()
111		m, ok := e.locks[key]
112		if !ok {
113			m = &sync.Mutex{}
114			e.locks[key] = m
115		}
116		e.locksMu.Unlock()
117		return m
118	}
119	
120	type execView struct {
121		state   *ExecutionState
122		payload any
123	}
124	
125	func (v execView) BusinessKey() string    { return v.state.BusinessKey }
126	func (v execView) SagaName() string       { return v.state.SagaName }
127	func (v execView) IdempotencyKey() string { return v.state.IdempotencyKey }
128	func (v execView) Payload() any           { return v.payload }
129	
130	func (v execView) SucceededSteps() []string {
131		return succeededNames(v.state)
132	}
133	
134	// Execute 按 Definition 执行一次 Saga 请求。
135	//
136	// 执行身份由业务键、Saga 定义与外部幂等键共同确定：
137	//   - 新身份：创建执行并执行未完成步骤；
138	//   - 同身份重试：不重复执行已确认成功的正向步骤或补偿步骤；
139	//     结果未确认的步骤允许被重新调用，重入次数累计在对应步骤的 Attempts，
140	//     动作自身须遵守幂等契约；
141	//   - 已到达终态：直接返回固定的终态结果，不再调用任何动作，也不再追加事件；
142	//   - 同业务键绑定不同定义：返回 ErrDefinitionConflict；
143	//   - 非法定义或缺失业务键/幂等键：返回 ErrInvalidDefinition。
144	//
145	// 调度分两种模式：定义中所有步骤都未声明前置（DependsOn 为空）时按 Steps
146	// 声明顺序逐个执行；任一步骤声明前置后进入依赖图模式——步骤在其全部前置
147	// 确认成功后才启动，无前置的步骤同时启动、并发执行，某一步确认后立即调度
148	// 因此就绪的后续步骤。任一正向动作预算耗尽仍失败时，停止调度未启动步骤，
149	// 已启动的兄弟动作继续运行到返回并各自原子提交结果，随后仅按确认成功顺序
150	// 的逆序补偿已确认成功的步骤；未执行到或未确认的步骤不补偿。
151	//
152	// 每一步确认后，状态与对应 Outbox 事件在同一个 Store 事务中原子提交，
153	// 然后才调度后续步骤。正向动作在其 ActionRetry 预算内的失败会在指定等待后
154	// 重试同一动作，中间失败不提交状态、不追加事件；预算耗尽仍失败才停止推进。
155	// 补偿动作同样可配置 CompensateRetry 预算，预算耗尽仍报错则固定为
156	// compensation_failed 终态。重试等待与动作本身都响应 ctx：ctx 取消时
157	// Execute 返回 ctx 的错误，不确认当前动作、不调度新的兄弟步骤、不启动补偿，
158	// 也不改变已经提交的执行状态。
159	func (e *Engine) Execute(ctx context.Context, def Definition, req ExecutionRequest) (Result, error) {
160		if err := ValidateDefinition(def); err != nil {
161			return Result{}, err
162		}
163		if strings.TrimSpace(req.BusinessKey) == "" || strings.TrimSpace(req.IdempotencyKey) == "" {
164			return Result{}, ErrInvalidDefinition
165		}
166		fp := fingerprint(def)
167	
168		mu := e.identityLock(req.BusinessKey, req.IdempotencyKey)
169		mu.Lock()
170		defer mu.Unlock()
171	
172		for {
173			if err := ctx.Err(); err != nil {
174				return Result{}, err
175			}
176			snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
177			if err != nil {
178				return Result{}, err
179			}
180			if snap.Bound && snap.Binding.Fingerprint != fp {
181				return Result{}, ErrDefinitionConflict
182			}
183			st := snap.State
184			if st == nil {
185				if err := e.createExecution(ctx, def, fp, req); err != nil {
186					return Result{}, err
187				}
188				continue
189			}
190			if st.Fingerprint != fp {
191				return Result{}, ErrDefinitionConflict
192			}
193			if st.Terminal() {
194				return toResult(st), nil
195			}
196	
197			switch st.Status {
198			case StatusRunning:
199				advanced, err := e.advanceForward(ctx, def, req, st)
200				if err != nil {
201					return Result{}, err
202				}
203				if !advanced {
204					// 所有步骤均已确认成功，重新读取以取得 completed 终态。
205					snap2, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
206					if err != nil {
207						return Result{}, err
208					}
209					return toResult(snap2.State), nil
210				}
211			case StatusCompensating:
212				done, err := e.advanceCompensation(ctx, def, req, st)
213				if err != nil {
214					return Result{}, err
215				}
216				if done {
217					return e.finishFailed(ctx, req)
218				}
219			default:
220				return Result{}, ErrInvalidDefinition
221			}
222		}
223	}
224	
225	// createExecution 在一个原子事务中建立执行状态并追加 started 事件。
226	func (e *Engine) createExecution(ctx context.Context, def Definition, fp string, req ExecutionRequest) error {
227		return e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
228			if b, ok := tx.Binding(); ok && b.Fingerprint != fp {
229				return ErrDefinitionConflict
230			}
231			if tx.State() != nil {
232				return nil // 并发情况下已由其它调用建立，直接沿用
233			}
234			steps := make([]StepState, len(def.Steps))
235			for i, s := range def.Steps {
236				steps[i] = StepState{Name: s.Name}
237			}
238			tx.Create(&ExecutionState{
239				SagaName:    def.Name,
240				Fingerprint: fp,
241				Status:      StatusRunning,
242				Steps:       steps,
243				Payload:     req.Payload,
244			})
245			tx.AppendEvent(EventExecutionStarted, EventPayload{
246				SagaName:       def.Name,
247				IdempotencyKey: req.IdempotencyKey,
248				Status:         StatusRunning,
249			})
250			return nil
251		})
252	}
253	
254	// advanceForward 推进正向步骤：顺序模式（定义未声明任何前置）执行下一个
255	// 未完成步骤；依赖图模式按前置满足情况并发调度全部就绪步骤。
256	// 动作在事务外调用，成功/失败结果与事件原子提交。返回 false 表示已无待执行步骤。
257	//
258	// 步骤配置了 ActionRetry 时，动作在预算内失败会等待指定时长后再次调用同一
259	// 动作；中间失败既不提交状态也不追加事件。等待与动作都响应 ctx：ctx 取消
260	// 时直接返回其错误，本次不确认动作、不启动补偿，已提交的步骤状态保持不变。
261	func (e *Engine) advanceForward(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
262		if hasDeps(def) {
263			return e.graphForward(ctx, def, req, st)
264		}
265	
266		idx := -1
267		for i := range st.Steps {
268			if st.Steps[i].Status == "" {
269				idx = i
270				break
271			}
272		}
273		if idx < 0 {
274			return false, nil
275		}
276		step := def.Steps[idx]
277	
278		// Attempts 记录本阶段（含预算内重试）动作的实际调用次数，成功或预算
279		// 耗尽后随状态一次提交；未确认的中间失败不会留下任何计数。
280		startedAt := e.now()
281		actionErr, attempts, err := e.runWithRetry(ctx, step.ActionRetry, func() error {
282			return step.Action(ctx, execView{state: st, payload: req.Payload})
283		})
284		if err != nil {
285			// 调用方取消（等待期间或动作随 ctx 结束）：不解释为业务失败，
286			// 未确认的步骤留待后续同身份重试，已确认的提交状态不变。
287			return false, err
288		}
289		finishedAt := e.now()
290		st.Steps[idx].Attempts = attempts
291		st.Steps[idx].StartedAt = startedAt
292	
293		if err := e.commitStepResult(ctx, def, req, idx, startedAt, finishedAt, attempts, actionErr); err != nil {
294			return false, err
295		}
296		return true, nil
297	}
298	
299	// hasDeps 报告定义是否声明了任何前置关系：是则进入依赖图调度模式，
300	// 否则保持按声明顺序逐个执行的顺序模式。
301	func hasDeps(def Definition) bool {
302		for _, s := range def.Steps {
303			if len(s.DependsOn) > 0 {
304				return true
305			}
306		}
307		return false
308	}
309	
310	// graphForward 依赖图模式的正向调度：前置全部确认成功的步骤可启动，无前置
311	// 的步骤同时启动；某一步确认后立即检查并启动因此就绪的后续步骤。
312	//
313	// 任一步骤预算耗尽仍失败（或 ctx 取消、提交出错）时停止调度未启动步骤，
314	// 但已启动的兄弟动作会继续运行到返回并各自原子提交结果，随后本函数才返回。
315	// 返回 false 表示没有任何步骤需要启动（全部已确认）。
316	func (e *Engine) graphForward(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
317		index := make(map[string]int, len(def.Steps))
318		for i, s := range def.Steps {
319			index[s.Name] = i
320		}
321		deps := make([][]int, len(def.Steps))
322		for i, s := range def.Steps {
323			for _, d := range s.DependsOn {
324				deps[i] = append(deps[i], index[d])
325			}
326		}
327	
328		// local 是调度器私有的状态镜像：随各动作提交结果而更新，用于计算就绪
329		// 步骤与构造动作启动时刻的只读视图。只有本 goroutine 读写它，工作
330		// goroutine 拿到的是启动时刻的克隆，无需加锁。
331		local := cloneState(st)
332		launched := make([]bool, len(def.Steps))
333		for i := range local.Steps {
334			if local.Steps[i].Status != "" {
335				launched[i] = true // 已确认（成功/失败）的步骤不再进入
336			}
337		}
338	
339		type outcome struct {
340			idx       int
341			actionErr error // 预算耗尽后的业务错误；nil 表示确认成功
342			callErr   error // ctx 取消或状态提交失败
343		}
344		results := make(chan outcome, len(def.Steps))
345		inFlight := 0
346		launchedAny := false
347		halted := false // 失败/取消/出错后停止调度新步骤
348		var firstErr error
349	
350		for {
351			if !halted {
352				for i := range def.Steps {
353					if launched[i] {
354						continue
355					}
356					ready := true
357					for _, d := range deps[i] {
358						if local.Steps[d].Status != StepResultSucceeded {
359							ready = false
360							break
361						}
362					}
363					if !ready {
364						continue
365					}
366					launched[i] = true
367					launchedAny = true
368					inFlight++
369					view := cloneState(local)
370					go func(i int, view *ExecutionState) {
371						step := def.Steps[i]
372						startedAt := e.now()
373						actionErr, attempts, callErr := e.runWithRetry(ctx, step.ActionRetry, func() error {
374							return step.Action(ctx, execView{state: view, payload: req.Payload})
375						})
376						if callErr != nil {
377							results <- outcome{idx: i, callErr: callErr}
378							return
379						}
380						finishedAt := e.now()
381						if err := e.commitStepResult(ctx, def, req, i, startedAt, finishedAt, attempts, actionErr); err != nil {
382							results <- outcome{idx: i, callErr: err}
383							return
384						}
385						results <- outcome{idx: i, actionErr: actionErr}
386					}(i, view)
387				}
388			}
389			if inFlight == 0 {
390				break
391			}
392			r := <-results
393			inFlight--
394			switch {
395			case r.callErr != nil:
396				if firstErr == nil {
397					firstErr = r.callErr
398				}
399				halted = true
400			case r.actionErr != nil:
401				local.Steps[r.idx].Status = StepResultFailed
402				halted = true // 停止调度未启动步骤；已启动的兄弟动作继续跑完并提交
403			default:
404				local.Steps[r.idx].Status = StepResultSucceeded
405				local.SucceededOrder = append(local.SucceededOrder, local.Steps[r.idx].Name)
406			}
407		}
408		return launchedAny, firstErr
409	}
410	
411	// commitStepResult 把一个正向步骤的确认结果（成功或预算耗尽的失败）与对应
412	// 事件在同一个 Store 事务中原子提交。顺序与依赖图模式共用本函数。
413	func (e *Engine) commitStepResult(ctx context.Context, def Definition, req ExecutionRequest, idx int, startedAt, finishedAt time.Time, attempts int, actionErr error) error {
414		step := def.Steps[idx]
415		return e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
416			cur := tx.State()
417			if cur == nil || cur.Terminal() {
418				return nil // 状态已被其它路径推进，本次结果丢弃
419			}
420			cs := &cur.Steps[idx]
421			cs.Attempts = attempts
422			cs.StartedAt = startedAt
423			cs.FinishedAt = finishedAt
424	
425			if actionErr == nil {
426				cs.Status = StepResultSucceeded
427				cs.LastError = ""
428				cur.SucceededOrder = append(cur.SucceededOrder, step.Name)
429				succeeded := succeededNames(cur)
430				if allSucceeded(cur) {
431					cur.Status = StatusCompleted
432					tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, StatusCompleted, succeeded))
433					tx.AppendEvent(EventExecutionCompleted, EventPayload{
434						SagaName:       def.Name,
435						IdempotencyKey: req.IdempotencyKey,
436						Status:         StatusCompleted,
437						SucceededSteps: succeeded,
438					})
439				} else {
440					// 依赖图模式下兄弟步骤可能已失败：此时执行处于 compensating，
441					// 成功结果仍照常提交，执行状态保持 compensating 不变。
442					tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, cur.Status, succeeded))
443				}
444				return nil
445			}
446	
447			errMsg := actionErr.Error()
448			cs.Status = StepResultFailed
449			cs.LastError = errMsg
450			if cur.Status != StatusCompensating {
451				// 首个失败驱动执行转入补偿；并发的兄弟步骤随后也失败时只记录
452				// 该步自身的错误，不覆盖执行级失败信息。
453				cur.FailedStep = step.Name
454				cur.FailureReason = errMsg
455				cur.Status = StatusCompensating
456			}
457			tx.AppendEvent(EventStepFailed, EventPayload{
458				SagaName:       def.Name,
459				IdempotencyKey: req.IdempotencyKey,
460				Step:           step.Name,
461				Status:         StatusCompensating,
462				Reason:         errMsg,
463				SucceededSteps: succeededNames(cur),
464			})
465			return nil
466		})
467	}
468	
469	// runWithRetry 在重试预算内反复调用同一动作。
470	//
471	// 返回 actionErr 为 nil 表示预算内成功（调用次数计入 attempts）；
472	// actionErr 非 nil、err 为 nil 表示预算耗尽仍失败，actionErr 为最近一次错误；
473	// err 非 nil 表示外层 context 已取消——可能发生在调用前、失败后的等待期间，
474	// 也可能动作刚返回（无论它返回 nil 还是错误），只要外层 context 已取消就
475	// 按取消处理：不确认动作，由调用方原样返回 ctx 错误。
476	func (e *Engine) runWithRetry(ctx context.Context, policy RetryPolicy, call func() error) (actionErr error, attempts int, err error) {
477		budget := normalizeRetry(policy)
478		for {
479			if err := ctx.Err(); err != nil {
480				return nil, attempts, err
481			}
482			attempts++
483			actionErr = call()
484			// 与基线一致：动作返回后先看外层 context，已取消则即使动作报告成功
485			// 也不确认该动作——结果可能已在下游生效，由同身份重入依赖动作幂等收敛。
486			if err := ctx.Err(); err != nil {
487				return nil, attempts, err
488			}
489			if actionErr == nil {
490				return nil, attempts, nil
491			}
492			if attempts >= budget.maxAttempts {
493				return actionErr, attempts, nil
494			}
495			// 仍有剩余次数：等待指定时长后再次调用同一动作，等待响应 context。
496			if budget.wait > 0 {
497				t := time.NewTimer(budget.wait)
498				select {
499				case <-ctx.Done():
500					t.Stop()
501					return nil, attempts, ctx.Err()
502				case <-t.C:
503				}
504			}
505		}
506	}
507	
508	// advanceCompensation 按确认成功顺序的逆序补偿下一个已确认成功的步骤。
509	// 返回 done=true 表示已无待补偿步骤，调用方应把执行收束为 failed 终态。
510	// 补偿动作返回错误时，执行在同一事务中固定为 compensation_failed 终态。
511	func (e *Engine) advanceCompensation(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
512		// 确认顺序的逆序：最后确认成功的步骤最先补偿。顺序模式下确认顺序即
513		// 声明顺序，与此前按声明逆序补偿的行为一致。
514		succeeded := succeededNames(st)
515		idx := -1
516		if len(succeeded) > 0 {
517			target := succeeded[len(succeeded)-1]
518			for i := range st.Steps {
519				if st.Steps[i].Name == target {
520					idx = i
521					break
522				}
523			}
524		}
525		if idx < 0 {
526			return true, nil
527		}
528		step := def.Steps[idx]
529	
530		// 未配置补偿动作的步骤视为补偿成功，不计数、不记录补偿时间。
531		var compErr error
532		var attempts int
533		var compensatedAt time.Time
534		if step.Compensate != nil {
535			// CompensationAttempts 记录本阶段（含预算内重试）补偿的实际调用次数，
536			// 成功或预算耗尽后随状态一次提交；中间失败不留计数、不追加事件。
537			var callErr error
538			compErr, attempts, callErr = e.runWithRetry(ctx, step.CompensateRetry, func() error {
539				return step.Compensate(ctx, execView{state: st, payload: req.Payload})
540			})
541			if callErr != nil {
542				return false, callErr
543			}
544			compensatedAt = e.now()
545			st.Steps[idx].CompensationAttempts = attempts
546		}
547	
548		err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
549			cur := tx.State()
550			if cur == nil || cur.Terminal() {
551				return nil
552			}
553			cs := &cur.Steps[idx]
554			if step.Compensate != nil {
555				cs.CompensationAttempts = attempts
556				cs.CompensatedAt = compensatedAt
557			}
558	
559			if compErr == nil {
560				cs.Status = StepResultCompensated
561				cs.LastError = ""
562				cur.Status = StatusCompensating
563				tx.AppendEvent(EventStepCompensated, EventPayload{
564					SagaName:       def.Name,
565					IdempotencyKey: req.IdempotencyKey,
566					Step:           step.Name,
567					Status:         StatusCompensating,
568				})
569				return nil
570			}
571	
572			errMsg := compErr.Error()
573			cs.Status = StepResultCompensationFailed
574			cs.LastError = errMsg
575			cur.FailedCompensationStep = step.Name
576			cur.CompensationError = errMsg
577			cur.Status = StatusCompensationFailed
578			tx.AppendEvent(EventStepCompensationFailed, EventPayload{
579				SagaName:       def.Name,
580				IdempotencyKey: req.IdempotencyKey,
581				Step:           step.Name,
582				Status:         StatusCompensationFailed,
583				Reason:         errMsg,
584				Attempt:        cs.CompensationAttempts,
585			})
586			tx.AppendEvent(EventCompensationFailed, EventPayload{
587				SagaName:       def.Name,
588				IdempotencyKey: req.IdempotencyKey,
589				Step:           step.Name,
590				Status:         StatusCompensationFailed,
591				Reason:         errMsg,
592			})
593			return nil
594		})
595		if err != nil {
596			return false, err
597		}
598		return false, nil
599	}
600	
601	// finishFailed 在补偿全部完成后把执行收束为 failed 终态并返回结果。
602	func (e *Engine) finishFailed(ctx context.Context, req ExecutionRequest) (Result, error) {
603		err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
604			cur := tx.State()
605			if cur == nil || cur.Terminal() {
606				return nil
607			}
608			cur.Status = StatusFailed
609			tx.AppendEvent(EventExecutionFailed, EventPayload{
610				SagaName:       cur.SagaName,
611				IdempotencyKey: req.IdempotencyKey,
612				Status:         StatusFailed,
613				Step:           cur.FailedStep,
614				Reason:         cur.FailureReason,
615			})
616			return nil
617		})
618		if err != nil {
619			return Result{}, err
620		}
621		snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
622		if err != nil {
623			return Result{}, err
624		}
625		return toResult(snap.State), nil
626	}
627	
628	// succeededNames 返回当前仍为成功状态的步骤名，按确认成功的先后顺序排列。
629	// 旧版本写入的状态没有确认顺序记录，回退为声明顺序（与当时的确认顺序一致）。
630	func succeededNames(st *ExecutionState) []string {
631		if len(st.SucceededOrder) == 0 {
632			var names []string
633			for _, s := range st.Steps {
634				if s.Status == StepResultSucceeded {
635					names = append(names, s.Name)
636				}
637			}
638			return names
639		}
640		status := make(map[string]string, len(st.Steps))
641		for _, s := range st.Steps {
642			status[s.Name] = s.Status
643		}
644		var names []string
645		for _, n := range st.SucceededOrder {
646			if status[n] == StepResultSucceeded {
647				names = append(names, n)
648			}
649		}
650		return names
651	}
652	
653	// allSucceeded 报告全部步骤是否均已确认成功。
654	func allSucceeded(st *ExecutionState) bool {
655		for _, s := range st.Steps {
656			if s.Status != StepResultSucceeded {
657				return false
658			}
659		}
660		return true
661	}
662	
663	func stepEvent(def Definition, req ExecutionRequest, step, status string, succeeded []string) EventPayload {
664		return EventPayload{
665			SagaName:       def.Name,
666			IdempotencyKey: req.IdempotencyKey,
667			Step:           step,
668			Status:         status,
669			SucceededSteps: succeeded,
670		}
671	}
672	
673	func toResult(st *ExecutionState) Result {
674		outcomes := make([]StepOutcome, len(st.Steps))
675		for i, s := range st.Steps {
676			r := s.Status
677			if r == "" {
678				r = StepResultPending
679			}
680			outcomes[i] = StepOutcome{
681				Name:                 s.Name,
682				Result:               r,
683				Attempts:             s.Attempts,
684				CompensationAttempts: s.CompensationAttempts,
685				Error:                s.LastError,
686				StartedAt:            s.StartedAt,
687				FinishedAt:           s.FinishedAt,
688			}
689		}
690		return Result{
691			BusinessKey:            st.BusinessKey,
692			SagaName:               st.SagaName,
693			IdempotencyKey:         st.IdempotencyKey,
694			Status:                 st.Status,
695			FailureReason:          st.FailureReason,
696			CompensationError:      st.CompensationError,
697			FailedStep:             st.FailedStep,
698			FailedCompensationStep: st.FailedCompensationStep,
699			Steps:                  outcomes,
700			Terminal:               st.Terminal(),
701		}
702	}
703	
704	// GetResult 查询某执行身份的当前结果，不执行任何动作。
705	// 未知执行身份（或 sagaName 与该执行的定义名不符）返回 ErrExecutionNotFound。
706	func (e *Engine) GetResult(ctx context.Context, sagaName, businessKey, idempotencyKey string) (Result, error) {
707		if strings.TrimSpace(sagaName) == "" || strings.TrimSpace(businessKey) == "" || strings.TrimSpace(idempotencyKey) == "" {
708			return Result{}, ErrInvalidDefinition
709		}
710		snap, err := e.store.LoadSnapshot(ctx, businessKey, idempotencyKey)
711		if err != nil {
712			return Result{}, err
713		}
714		if snap.State == nil || snap.State.SagaName != sagaName {
