1	package txsaga
2	
3	import (
4		"context"
5		"errors"
6		"time"
7	)
8	
9	// Publisher 由调用方实现，负责把一条 Outbox 事件发送到实际的下游
10	// （消息代理、HTTP 回调、其它进程内通道等）。本包不提供任何具体中间件适配。
11	//
12	// 实现应当满足至少一次投递语义：返回 error 时事件会被保留并可再次领取，
13	// 因此下游消费侧需要自身幂等。返回 nil 即视为投递成功，事件被标记已投递。
14	type Publisher interface {
15		// Publish 发送单个事件。event.Payload 为结构化负载，可用 encoding/json 序列化。
16		Publish(ctx context.Context, event Event) error
17	}
18	
19	// PublisherFunc 让普通函数满足 Publisher 接口。
20	type PublisherFunc func(ctx context.Context, event Event) error
21	
22	// Publish 实现 Publisher 接口。
23	func (f PublisherFunc) Publish(ctx context.Context, event Event) error { return f(ctx, event) }
24	
25	// Relay 在 Store 与 Publisher 之间搬运 Outbox 事件：
26	// 领取待投递事件、交给 Publisher、成功 Ack、失败 Nack 后保留并允许重试。
27	// Relay 可被多个 worker 并发使用；零值不可用，请用 NewRelay 创建。
28	type Relay struct {
29		store     Store
30		publisher Publisher
31		// batch 单次领取上限。
32		batch int
33		// retryBackoff 一批事件全部发送失败后的再次领取间隔。
34		retryBackoff time.Duration
35		// idleWait 没有待投递事件时的轮询等待。
36		idleWait time.Duration
37		// leaseTTL > 0 时启用带租约领取：worker 在 Publish/Ack/Nack 前退出，
38		// 事件在租约到期后的下一轮自动恢复；0 表示沿用普通领取的默认行为。
39		leaseTTL time.Duration
40		// now 等时间依赖直接使用 time 包标准行为。
41		sleep func(ctx context.Context, d time.Duration) error
42	}
43	
44	// RelayOption 配置 Relay。
45	type RelayOption func(*Relay)
46	
47	// WithBatch 设置单次领取事件数，默认 16。
48	func WithBatch(n int) RelayOption {
49		return func(r *Relay) {
50			if n > 0 {
51				r.batch = n
52			}
53		}
54	}
55	
56	// WithRetryBackoff 设置发送失败后的重试间隔，默认 200ms。
57	func WithRetryBackoff(d time.Duration) RelayOption {
58		return func(r *Relay) {
59			if d > 0 {
60				r.retryBackoff = d
61			}
62		}
63	}
64	
65	// WithIdleWait 设置无事件时的轮询间隔，默认 500ms。
66	func WithIdleWait(d time.Duration) RelayOption {
67		return func(r *Relay) {
68			if d > 0 {
69				r.idleWait = d
70			}
71		}
72	}
73	
74	// WithClaimLease 启用带租约领取并设置租约时长。
75	//
76	// 仅正时长生效；传入 0 或负时长不启用租约，Relay 沿用普通 ClaimPendingEvents
77	// 的默认行为。启用后，每次领取的事件在 ttl 内不会被再次领取；worker 在
78	// Publish、Ack 或 Nack 前退出时，事件于租约到期后的下一次 DeliverOnce/Run
79	// 自动恢复重投，从而保证至少一次投递。Store 必须实现 ClaimLeaseStore，
80	// 否则 DeliverOnce 返回 ErrClaimLeaseUnsupported（可 errors.Is）。
81	func WithClaimLease(ttl time.Duration) RelayOption {
82		return func(r *Relay) {
83			if ttl > 0 {
84				r.leaseTTL = ttl
85			}
86		}
87	}
88	
89	// NewRelay 创建事件投递器。
90	func NewRelay(store Store, publisher Publisher, opts ...RelayOption) *Relay {
91		r := &Relay{
92			store:        store,
93			publisher:    publisher,
94			batch:        16,
95			retryBackoff: 200 * time.Millisecond,
96			idleWait:     500 * time.Millisecond,
97		}
98		r.sleep = sleepWithContext
99		for _, opt := range opts {
100			opt(r)
101		}
102		return r
103	}
104	
105	func sleepWithContext(ctx context.Context, d time.Duration) error {
106		t := time.NewTimer(d)
107		defer t.Stop()
108		select {
109		case <-ctx.Done():
110			return ctx.Err()
111		case <-t.C:
112			return nil
113		}
114	}
115	
116	// RelayResult 是单轮投递的结果统计。
117	type RelayResult struct {
118		// Claimed 本轮领取的事件数。
119		Claimed int
120		// Delivered 发送成功并 Ack 的事件数。
121		Delivered int
122		// Failed 发送失败并 Nack 保留的事件数。
123		Failed int
124	}
125	
126	// DeliverOnce 执行一轮领取与投递，不阻塞等待。没有事件时立即返回空结果。
127	// 单个事件发送失败不影响同批其它事件；失败事件被 Nack，可在后续轮次继续领取。
128	//
129	// 通过 WithClaimLease 启用租约且 Store 未实现 ClaimLeaseStore 时，
130	// 返回包装了 ErrClaimLeaseUnsupported 的错误（可 errors.Is 判定）。
131	func (r *Relay) DeliverOnce(ctx context.Context) (RelayResult, error) {
132		if r.leaseTTL > 0 {
133			leased, ok := r.store.(ClaimLeaseStore)
134			if !ok {
135				return RelayResult{}, ErrClaimLeaseUnsupported
136			}
137			return r.deliverOnceLeased(ctx, leased)
138		}
139		return r.deliverOnce(ctx)
140	}
141	
142	// deliverOnce 是未启用租约时的默认路径：领取即锁定，失败立即退回。
143	func (r *Relay) deliverOnce(ctx context.Context) (RelayResult, error) {
144		events, err := r.store.ClaimPendingEvents(ctx, r.batch)
145		if err != nil {
146			return RelayResult{}, err
147		}
148		res := RelayResult{Claimed: len(events)}
149		for _, ev := range events {
150			if err := ctx.Err(); err != nil {
151				// 退出前把尚未处理的已领取事件退回，避免它们滞留到进程重启。
152				_ = r.store.NackEvent(ctx, ev.ID)
153				res.Failed++
154				continue
155			}
156			if err := r.publisher.Publish(ctx, *ev); err != nil {
157				if nackErr := r.store.NackEvent(ctx, ev.ID); nackErr != nil {
158					return res, nackErr
159				}
160				res.Failed++
161				continue
162			}
163			if err := r.store.AckEvent(ctx, ev.ID); err != nil {
164				return res, err
165			}
166			res.Delivered++
167		}
168		return res, nil
169	}
170	
171	// deliverOnceLeased 是启用租约后的投递路径。
172	//
173	// 取消语义：
174	//   - 领取后、Publish 前 ctx 已取消：事件从未交给 Publish，按当前 ClaimID
175	//     立即 Nack，等不到租约到期；
176	//   - Publish 进行中取消：按 Publish 的返回结果处理，nil 走 Ack，error 走
177	//     Nack，不因 ctx 取消改变结论；
178	//   - worker 在任何一步退出（未 Nack）：租约到期后事件自动恢复重投。
179	//
180	// Ack/Nack 使用独立上下文，避免调用方 ctx 已取消导致确认/退回被 Store
181	// 拒绝而被迫等待租约到期。旧 ClaimID（租约已到期、事件被他人重新领取）
182	// 返回 ErrStaleClaim 时不作任何操作：当前事件与新租约由接管方负责。
183	func (r *Relay) deliverOnceLeased(ctx context.Context, store ClaimLeaseStore) (RelayResult, error) {
184		claims, err := store.ClaimPendingEventsLeased(ctx, r.leaseTTL, r.batch)
185		if err != nil {
186			return RelayResult{}, err
187		}
188		res := RelayResult{Claimed: len(claims)}
189		for _, c := range claims {
190			if err := ctx.Err(); err != nil {
191				if nackErr := store.NackLeasedEvent(context.Background(), c.Event.ID, c.ClaimID); nackErr != nil &&
192					!errors.Is(nackErr, ErrStaleClaim) {
193					return res, nackErr
194				}
195				res.Failed++
196				continue
197			}
198			pubErr := r.publisher.Publish(ctx, *c.Event)
199			if pubErr != nil {
200				if nackErr := store.NackLeasedEvent(context.Background(), c.Event.ID, c.ClaimID); nackErr != nil &&
201					!errors.Is(nackErr, ErrStaleClaim) {
202					return res, nackErr
203				}
204				res.Failed++
205				continue
206			}
207			if ackErr := store.AckLeasedEvent(context.Background(), c.Event.ID, c.ClaimID); ackErr != nil &&
208				!errors.Is(ackErr, ErrStaleClaim) {
209				return res, ackErr
210			}
211			res.Delivered++
212		}
213		return res, nil
214	}
215	
216	// Run 循环执行投递，直到 ctx 被取消。至少一轮成功投递后返回 ctx.Err()。
217	// 全部事件发送失败的批次后按重试间隔等待；无事件时按空闲间隔等待。
218	func (r *Relay) Run(ctx context.Context) error {
219		for {
220			if err := ctx.Err(); err != nil {
221				return err
222			}
223			res, err := r.DeliverOnce(ctx)
224			if err != nil {
225				return err
226			}
227			var wait time.Duration
228			switch {
229			case res.Claimed == 0:
230				wait = r.idleWait
231			case res.Failed > 0 && res.Delivered == 0:
232				wait = r.retryBackoff
233			default:
234				wait = 0 // 本轮有成功投递，立即继续领取，尽快排空积压
235			}
236			if wait > 0 {
237				if err := r.sleep(ctx, wait); err != nil {
238					return err
239				}
240			}
241		}
242	}
243

