1	package txsaga
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"testing"
8		"time"
9	)
10	
11	// flakyAction 前 failTimes 次返回固定错误，之后成功，并通过 recorder 记录调用。
12	func flakyAction(rec *recorder, name string, failTimes int) ActionFunc {
13		n := 0
14		return func(_ context.Context, _ ExecutionView) error {
15			rec.call("do:" + name)
16			n++
17			if n <= failTimes {
18				return errors.New("transient-" + name)
19			}
20			return nil
21		}
22	}
23	
24	// flakyCompensateN 前 failTimes 次返回固定错误，之后成功，并暴露调用次数。
25	func flakyCompensateN(rec *recorder, name string, failTimes int) (CompensationFunc, func() int) {
26		n := 0
27		return func(_ context.Context, _ ExecutionView) error {
28			rec.call("undo:" + name)
29			n++
30			if n <= failTimes {
31				return errors.New("comp-transient-" + name)
32			}
33			return nil
34		}, func() int { return n }
35	}
36	
37	func retrySagaDef(rec *recorder, chargeFails, shipFails int, actionRetry RetryPolicy) Definition {
38		mk := func(name string, fails int) Step {
39			return Step{
40				Name:        name,
41				Action:      flakyAction(rec, name, fails),
42				Compensate:  func(_ context.Context, _ ExecutionView) error { rec.call("undo:" + name); return nil },
43				ActionRetry: actionRetry,
44			}
45		}
46		return Definition{
47			Name:    "retry-saga",
48			Version: "v1",
49			Steps:   []Step{mk("reserve", 0), mk("charge", chargeFails), mk("ship", shipFails)},
50		}
51	}
52	
53	func TestActionRetrySucceedsWithinBudget(t *testing.T) {
54		store := NewMemoryStore()
55		eng := NewEngine(store)
56		rec := &recorder{}
57		// charge 前 2 次失败、第 3 次成功；预算 3 次、失败后立即重试。
58		def := retrySagaDef(rec, 2, 0, RetryPolicy{MaxAttempts: 3})
59	
60		res, err := eng.Execute(context.Background(), def, ExecutionRequest{
61			BusinessKey: "r-1", IdempotencyKey: "req-1",
62		})
63		if err != nil {
64			t.Fatalf("Execute: %v", err)
65		}
66		if res.Status != StatusCompleted || !res.Terminal {
67			t.Fatalf("status=%s terminal=%v", res.Status, res.Terminal)
68		}
69		// charge 共调用 3 次，其余各 1 次。
70		if got := rec.snapshot(); fmt.Sprint(got) !=
71			"[do:reserve do:charge do:charge do:charge do:ship]" {
72			t.Fatalf("calls = %v", got)
73		}
74		if res.Steps[1].Attempts != 3 {
75			t.Fatalf("charge attempts=%d want 3", res.Steps[1].Attempts)
76		}
77		if res.Steps[1].Error != "" {
78			t.Fatalf("error must be cleared after success: %q", res.Steps[1].Error)
79		}
80		if res.Steps[0].Attempts != 1 || res.Steps[2].Attempts != 1 {
81			t.Fatalf("other step attempts = %d,%d want 1,1", res.Steps[0].Attempts, res.Steps[2].Attempts)
82		}
83	
84		// 中间失败不追加事件：仍是 started -> 每步一次 succeeded -> completed。
85		events, _ := store.ClaimPendingEvents(context.Background(), 100)
86		wantTypes := []string{
87			EventExecutionStarted,
88			EventStepSucceeded, EventStepSucceeded, EventStepSucceeded,
89			EventExecutionCompleted,
90		}
91		if len(events) != len(wantTypes) {
92			t.Fatalf("events=%d want=%d (%v)", len(events), len(wantTypes), eventTypes(events))
93		}
94		for i, ev := range events {
95			if ev.Type != wantTypes[i] {
96				t.Fatalf("event[%d]=%s want %s, all=%v", i, ev.Type, wantTypes[i], eventTypes(events))
97			}
98		}
99	}
100	
101	func TestActionRetryExhaustedTriggersCompensation(t *testing.T) {
102		store := NewMemoryStore()
103		eng := NewEngine(store)
104		rec := &recorder{}
105		// ship 连续失败 3 次耗尽预算；reserve、charge 已确认成功需逆序补偿。
106		def := retrySagaDef(rec, 0, 3, RetryPolicy{MaxAttempts: 3})
107	
108		res, err := eng.Execute(context.Background(), def, ExecutionRequest{
109			BusinessKey: "r-2", IdempotencyKey: "req-2",
110		})
111		if err != nil {
112			t.Fatalf("Execute: %v", err)
113		}
114		if res.Status != StatusFailed || !res.Terminal {
115			t.Fatalf("status=%s want failed", res.Status)
116		}
117		if res.FailedStep != "ship" || res.FailureReason != "transient-ship" {
118			t.Fatalf("failure info: %+v", res)
119		}
120		ship := res.Steps[2]
121		if ship.Result != StepResultFailed || ship.Attempts != 3 || ship.Error != "transient-ship" {
122			t.Fatalf("ship outcome = %+v", ship)
123		}
124		if got := rec.snapshot(); fmt.Sprint(got) !=
125			"[do:reserve do:charge do:ship do:ship do:ship undo:charge undo:reserve]" {
126			t.Fatalf("calls = %v", got)
127		}
128	
129		// 中间重试不产生事件：仅 started、两次 succeeded、一次 failed、两次补偿、failed。
130		events, _ := store.ClaimPendingEvents(context.Background(), 100)
131		wantTypes := []string{
132			EventExecutionStarted,
133			EventStepSucceeded, // reserve
134			EventStepSucceeded, // charge
135			EventStepFailed,    // ship（仅在预算耗尽时提交一次）
136			EventStepCompensated, EventStepCompensated,
137			EventExecutionFailed,
138		}
139		if len(events) != len(wantTypes) {
140			t.Fatalf("events=%d want=%d (%v)", len(events), len(wantTypes), eventTypes(events))
141		}
142		for i, ev := range events {
143			if ev.Type != wantTypes[i] {
144				t.Fatalf("event[%d]=%s want %s, all=%v", i, ev.Type, wantTypes[i], eventTypes(events))
145			}
146		}
147	}
148	
149	func TestCompensationRetrySucceedsWithinBudget(t *testing.T) {
150		store := NewMemoryStore()
151		eng := NewEngine(store)
152		rec := &recorder{}
153	
154		// ship 正向失败（默认预算 1，一次失败即转补偿）；此前已确认成功的步骤
155		// 按逆序补偿：先 charge（前 2 次失败、第 3 次成功），再 reserve（始终成功）。
156		chargeComp, chargeCompN := flakyCompensateN(rec, "charge", 2)
157		reserveComp := func(_ context.Context, _ ExecutionView) error { rec.call("undo:reserve"); return nil }
158		def := Definition{
159			Name: "comp-retry-saga", Version: "v1",
160			Steps: []Step{
161				{
162					Name:       "reserve",
163					Action:     flakyAction(rec, "reserve", 0),
164					Compensate: reserveComp,
165				},
166				{
167					Name:            "charge",
168					Action:          flakyAction(rec, "charge", 0),
169					Compensate:      chargeComp,
170					CompensateRetry: RetryPolicy{MaxAttempts: 3},
171				},
172				{Name: "ship", Action: flakyAction(rec, "ship", 1)},
173			},
174		}
175	
176		res, err := eng.Execute(context.Background(), def, ExecutionRequest{
177			BusinessKey: "r-3", IdempotencyKey: "req-3",
178		})
179		if err != nil {
180			t.Fatalf("Execute: %v", err)
181		}
182		if res.Status != StatusFailed || !res.Terminal {
183			t.Fatalf("status=%s want failed", res.Status)
184		}
185		if chargeCompN() != 3 {
186			t.Fatalf("charge compensation calls=%d want 3", chargeCompN())
187		}
188		if got := res.Steps[1].CompensationAttempts; got != 3 {
189			t.Fatalf("charge CompensationAttempts=%d want 3", got)
190		}
191		if res.Steps[1].Result != StepResultCompensated {
192			t.Fatalf("charge result=%s want compensated", res.Steps[1].Result)
193		}
194		if got := rec.snapshot(); fmt.Sprint(got) !=
195			"[do:reserve do:charge do:ship undo:charge undo:charge undo:charge undo:reserve]" {
196			t.Fatalf("calls = %v", got)
197		}
198	
199		events, _ := store.ClaimPendingEvents(context.Background(), 100)
200		wantTypes := []string{
201			EventExecutionStarted,
202			EventStepSucceeded, // reserve
203			EventStepSucceeded, // charge
204			EventStepFailed,    // ship
205			EventStepCompensated, EventStepCompensated,
206			EventExecutionFailed,
207		}
