222	
223		// ship 正向失败；逆序先补偿 charge，其补偿预算 3 次全部失败 =>
224		// compensation_failed；reserve 的补偿不得被调用。
225		reserveComp, reserveCompN := flakyCompensateN(rec, "reserve", 0)
226		chargeComp, chargeCompN := flakyCompensateN(rec, "charge", 99)
227		def := Definition{
228			Name: "comp-retry-fail", Version: "v1",
229			Steps: []Step{
230				{Name: "reserve", Action: flakyAction(rec, "reserve", 0), Compensate: reserveComp},
231				{
232					Name:            "charge",
233					Action:          flakyAction(rec, "charge", 0),
234					Compensate:      chargeComp,
235					CompensateRetry: RetryPolicy{MaxAttempts: 3},
236				},
237				{Name: "ship", Action: flakyAction(rec, "ship", 1)},
238			},
239		}
