266		events, _ := store.ClaimPendingEvents(context.Background(), 100)
267		var compFailPayload *EventPayload
268		for _, ev := range events {
269			if ev.Type == EventStepCompensationFailed {
270				p := ev.Payload.(EventPayload)
271				compFailPayload = &p
272			}
273		}
274		if compFailPayload == nil {
